### Vector Store Configuration

```python
class VectorStoreConfig:
    """Configuration for vector database integration."""

    def __init__(self):
        self.provider = os.getenv('VECTOR_DB_PROVIDER', 'chroma')
        self.connection_string = os.getenv('VECTOR_DB_CONNECTION')
        self.index_name = os.getenv('VECTOR_DB_INDEX', 'mkdocs-content')
        self.similarity_metric = 'cosine'
        self.top_k = 10  # Number of results to retrieve

    def create_vector_store(self):
        """Create a vector store with the specified configuration."""
        if self.provider == 'pinecone':
            return PineconeVectorStore(
                connection=self.connection_string,
                index=self.index_name,
                metric=self.similarity_metric
            )
        elif self.provider == 'chroma':
            return ChromaVectorStore(
                path=self.connection_string or './chroma_db',
                collection=self.index_name
            )
        else:
            raise ValueError(f"Unsupported vector store provider: {self.provider}")
