### RESTful API Endpoints

```python
from flask import Flask, request, jsonify
from rag_service import RAGService

app = Flask(__name__)
rag_service = RAGService()

@app.route('/api/chat', methods=['POST'])
def chat():
    """Chat interface endpoint."""
    data = request.get_json()

    response = rag_service.process_query(
        query=data['message'],
        session_id=data.get('sessionId'),
        history=data.get('history', [])
    )

    return jsonify({
        'response': response.text,
        'sources': response.sources,
        'confidence': response.confidence,
        'suggestions': response.follow_up_questions
    })

@app.route('/api/search', methods=['GET'])
def search():
    """Semantic search endpoint."""
    query = request.args.get('q')
    top_k = int(request.args.get('top_k', 10))

    results = rag_service.semantic_search(
        query=query,
        top_k=top_k
    )

    return jsonify({
        'results': results,
        'query': query,
        'total': len(results)
    })

@app.route('/api/summarize', methods=['POST'])
def summarize():
    """Content summarization endpoint."""
    data = request.get_json()

    summary = rag_service.summarize_content(
        content_ids=data['contentIds'],
        summary_type=data.get('type', 'executive')
    )

    return jsonify({
        'summary': summary.text,
        'sources': summary.sources,
        'length': summary.word_count
    })
````

