### Search Enhancement

```javascript
// Enhanced search with RAG
class EnhancedSearch {
  constructor() {
    this.ragAPI = new RAGAPIClient();
    this.traditionalSearch = new MkDocsSearch();
  }

  async search(query) {
    // Run both traditional and semantic search in parallel
    const [traditionalResults, semanticResults] = await Promise.all([
      this.traditionalSearch.search(query),
      this.ragAPI.semanticSearch(query),
    ]);

    // Merge and rank results
    return this.mergeResults(traditionalResults, semanticResults);
  }

  mergeResults(traditional, semantic) {
    // Implement hybrid ranking algorithm
    const merged = [];

    // Add semantic results with boost for relevance
    semantic.forEach((result) => {
      merged.push({
        ...result,
        score: result.score * 1.2, // Boost semantic results
        type: 'semantic',
      });
    });

    // Add traditional results
    traditional.forEach((result) => {
      if (!this.isDuplicate(result, merged)) {
        merged.push({
          ...result,
          type: 'traditional',
        });
      }
    });

    // Sort by combined score
    return merged.sort((a, b) => b.score - a.score);
  }
}
```
